   */
  placement?: AppShellPlacement;
  /**
   * Scroll behavior for the inspector column.
   *
   * - `fixed` — stays in the viewport while the page scrolls.
   * - `relative` — scrolls with the page in normal document flow.
   *
   * @defaultValue "fixed"
