import { cn } from "@pisagor/utils";
import type { ComponentProps } from "react";
import { Button, type ButtonProps } from "../button";
import { Tooltip, type TooltipProps } from "../tooltip";
import type {
  AppShellPlacement,
  AppShellRegionPosition,
} from "./app-shell.context";
import { useAppShell } from "./app-shell.context";
import { APP_SHELL_RAIL_WIDTH } from "./constants";
import { AppShellRailContext, useAppShellRail } from "./rail.context";
import {
  gridAreaFor,
  regionPositionClasses,
  regionVarFor,
  useRegionWidth,
  useRegisteredRailState,
} from "./region";

export interface AppShellRailProps extends ComponentProps<"aside"> {
  /**
   * Grid column side for the rail.
   *
   * @defaultValue "start"
   */
  placement?: AppShellPlacement;
  /**
   * Scroll behavior for the rail column.
   *
   * - `fixed` — stays in the viewport while the page scrolls.
   * - `relative` — scrolls with the page in normal document flow.
   *
   * @defaultValue "fixed"
   */
  position?: AppShellRegionPosition;
  activeRailId?: string;
  defaultActiveRailId?: string;
  onActiveRailIdChange?: (id: string) => void;
}

export interface AppShellRailItemProps extends ButtonProps {
  /** When `railId` is set, marks this item active when it matches the rail's active id. */
  isActive?: boolean;
  /**
   * Opens the panel on the same side as the parent rail when clicked.
   *
   * @defaultValue false
   */
  opensPanel?: boolean;
  /**
   * Which panel side to open when `opensPanel` is true.
   *
   * @defaultValue parent `AppShell.Rail` `placement`
   */
  panelPlacement?: AppShellPlacement;
  railId?: string;
  tooltip?: string | Omit<TooltipProps, "children">;
}

export function AppShellRail({
  placement = "start",
  position = "fixed",
  defaultActiveRailId,
  activeRailId: activeRailIdProp,
  children,
  onActiveRailIdChange,
  className,
  style,
  ...rest
}: AppShellRailProps) {
  const { railStates, slots } = useAppShell();
  const regionVar = regionVarFor(placement, "rail");
  const railState = useRegisteredRailState({
    activeRailId: activeRailIdProp,
    defaultActiveRailId,
    onActiveRailIdChange,
    placement,
    statesRef: railStates,
  });

  useRegionWidth(regionVar, APP_SHELL_RAIL_WIDTH);

  return (
    <AppShellRailContext value={railState}>
      <aside
        {...rest}
        className={cn(
          slots.rail(),
          placement === "start" ? "border-e" : "border-s",
          regionPositionClasses(slots, position, "column"),
          className,
        )}
        data-part="rail"
        data-placement={placement}
        data-position={position}
        data-scope="app-shell"
        style={{ gridArea: gridAreaFor(placement, "rail"), ...style }}
      >
        {children}
      </aside>
    </AppShellRailContext>
  );
}

export function AppShellRailItem({
  panelPlacement: panelPlacementProp,
  size = "icon-md",
  variant = "ghost",
  isActive,
  opensPanel = false,
  railId,
  tooltip,
  onClick,
  className,
  ...rest
}: AppShellRailItemProps) {
  const {
    activeRailId,
    placement: railPlacement,
    setActiveRailId,
  } = useAppShellRail();
  const panelPlacement = panelPlacementProp ?? railPlacement;
  const { panelStates, slots } = useAppShell();
  const active = isActive ?? (railId !== undefined && activeRailId === railId);

  const button = (
    <Button
      {...rest}
      aria-current={active ? "page" : undefined}
      className={slots.railItem({ className })}
      clickEffect={false}
      data-active={active}
      data-part="rail-item"
      data-rail-id={railId}
      data-scope="app-shell"
      onClick={(event) => {
        onClick?.(event);
        if (railId) {
          setActiveRailId(railId);
        }
        if (opensPanel) {
          panelStates.current[panelPlacement]?.setOpen(true);
        }
      }}
      size={size}
      variant={variant}
    />
  );

  if (!tooltip) {
    return button;
  }

  const tooltipProps =
    typeof tooltip === "string" ? { content: tooltip } : tooltip;

  return (
    <Tooltip
      {...tooltipProps}
      positioning={{
        placement: railPlacement === "end" ? "left" : "right",
        ...tooltipProps.positioning,
      }}
    >
      {button}
    </Tooltip>
  );
}

// #region Display Names
AppShellRail.displayName = "AppShell.Rail";
AppShellRailItem.displayName = "AppShell.RailItem";
// #endregion

import { useUncontrolled } from "@mantine/hooks";
import type { AppShellRecipe } from "@pisagor/recipes";

import { type RefObject, useCallback, useLayoutEffect, useMemo } from "react";
import type {
  AppShellFixedStackVar,
  AppShellPlacement,
  AppShellRegionPosition,
  AppShellRegionVar,
  AppShellResizableProps,
  AppShellSideState,
} from "./app-shell.context";
import {
  type AppShellRailState,
  useAppShell,
  useSideState,
} from "./app-shell.context";

export function useRegionWidth(name: AppShellRegionVar, width: string) {
  const { setRegionVar } = useAppShell();

  useLayoutEffect(() => {
    setRegionVar(name, width);
    return () => {
      setRegionVar(name, "0px");
    };
  }, [name, setRegionVar, width]);
}

export function regionVarFor(
  placement: AppShellPlacement,
  region: "inspector" | "panel" | "rail",
) {
  return `--app-shell-${placement}-${region}-width` as AppShellRegionVar;
}

export function gridAreaFor(
  placement: AppShellPlacement,
  region: "inspector" | "panel" | "rail",
) {
  return `${placement}-${region}` as const;
}

export function mergeResizableProps(
  defaults: Required<
    Pick<AppShellResizableProps, "enabled" | "handlePosition">
  >,
  override?: AppShellResizableProps,
): Required<Pick<AppShellResizableProps, "enabled" | "handlePosition">> {
  return {
    enabled: override?.enabled ?? defaults.enabled,
    handlePosition: override?.handlePosition ?? defaults.handlePosition,
  };
}

export function useShellRegionResizeCallbacks(regionVar: AppShellRegionVar) {
  const { setRegionResizing, setRegionVar } = useAppShell();

  return useMemo(
    () => ({
      onResizeChange: (nextWidth: number) => {
        setRegionVar(regionVar, `${nextWidth}px`);
      },
      onResizeEnd: () => setRegionResizing(false),
      onResizeStart: () => setRegionResizing(true),
    }),
    [regionVar, setRegionResizing, setRegionVar],
  );
}

export function regionPositionClasses(
  slots: AppShellRecipe,
  position: AppShellRegionPosition = "fixed",
  orientation: "column" | "row" = "column",
  rowLayer?: "banner" | "header" | "navigation",
  columnLayer?: "inspector",
) {
  if (position === "relative") {
    return orientation === "column"
      ? slots.regionRelativeColumn()
      : slots.regionRelativeRow();
  }

  if (orientation === "column") {
    if (columnLayer === "inspector") {
      return slots.regionStickyInspector();
    }

    return slots.regionStickyColumn();
  }

  if (rowLayer === "banner") {
    return slots.regionStickyBanner();
  }

  if (rowLayer === "navigation") {
    return slots.regionStickyNavigation();
  }

  return slots.regionStickyHeader();
}

export function useSyncFixedRegionHeight(
  ref: RefObject<HTMLElement | null>,
  position: AppShellRegionPosition,
  cssVar: AppShellFixedStackVar,
) {
  const { setFixedStackVar } = useAppShell();

  useLayoutEffect(() => {
    const element = ref.current;

    if (position !== "fixed" || !element) {
      setFixedStackVar(cssVar, "0px");
      return;
    }

    const syncHeight = () => {
      setFixedStackVar(cssVar, `${element.offsetHeight}px`);
    };

    syncHeight();
    const observer = new ResizeObserver(syncHeight);
    observer.observe(element);

    return () => {
      observer.disconnect();
      setFixedStackVar(cssVar, "0px");
    };
  }, [cssVar, position, ref, setFixedStackVar]);
}

export function useAppShellSideOpen(
  placement: AppShellPlacement,
  statesRef: RefObject<Partial<Record<AppShellPlacement, AppShellSideState>>>,
) {
  const { regionRevision } = useAppShell();
  void regionRevision;

  return statesRef.current[placement]?.open ?? false;
}

export function useRegisteredSideState({
  placement,
  defaultOpen,
  controlledOpen,
  statesRef,
  onOpenChange,
}: {
  controlledOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placement: AppShellPlacement;
  statesRef: RefObject<Partial<Record<AppShellPlacement, AppShellSideState>>>;
}) {
  const { notifyRegionChange } = useAppShell();
  const side = useSideState({ controlledOpen, defaultOpen, onOpenChange });

  const setOpen = useCallback(
    (value: boolean | ((current: boolean) => boolean)) => {
      side.setOpen(value);
      notifyRegionChange();
    },
    [notifyRegionChange, side.setOpen],
  );

  const toggle = useCallback(() => {
    side.toggle();
    notifyRegionChange();
  }, [notifyRegionChange, side.toggle]);

  const registeredSide = useMemo(
    () => ({
      open: side.open,
      setOpen,
      toggle,
    }),
    [setOpen, side.open, toggle],
  );

  statesRef.current[placement] = registeredSide;

  useLayoutEffect(() => {
    notifyRegionChange();
  }, [notifyRegionChange]);

  useLayoutEffect(() => {
    return () => {
      delete statesRef.current[placement];
    };
  }, [placement, statesRef]);

  return registeredSide;
}

export function useRegisteredRailState({
  placement,
  defaultActiveRailId,
  activeRailId: activeRailIdProp,
  statesRef,
  onActiveRailIdChange,
}: {
  activeRailId?: string;
  defaultActiveRailId?: string;
  onActiveRailIdChange?: (id: string) => void;
  placement: AppShellPlacement;
  statesRef: RefObject<Partial<Record<AppShellPlacement, AppShellRailState>>>;
}) {
  const [activeRailId, setActiveRailId] = useUncontrolled({
    defaultValue: defaultActiveRailId,
    onChange: onActiveRailIdChange,
    value: activeRailIdProp,
  });

  const railState = useMemo(
    () => ({ activeRailId, placement, setActiveRailId }),
    [activeRailId, placement, setActiveRailId],
  );

  statesRef.current[placement] = railState;

  useLayoutEffect(() => {
    return () => {
      delete statesRef.current[placement];
    };
  }, [placement, statesRef]);

  return railState;
}

import type { ReactNode } from "react";
import { Button, type ButtonProps } from "../button";
import { Swap } from "../swap";
import type { AppShellPlacement } from "./app-shell.context";
import { useAppShell } from "./app-shell.context";

export function AppShellSideTrigger({
  placement,
  defaultOff,
  defaultOn,
  open,
  "aria-label": ariaLabel,
  children,
  off: offContent,
  on: onContent,
  toggle,
  onClick,
  className,
  ...rest
}: {
  "aria-label"?: string;
  children?: ReactNode;
  defaultOff: ReactNode;
  defaultOn: ReactNode;
  onClick?: ButtonProps["onClick"];
  open: boolean;
  placement: AppShellPlacement;
  toggle: () => void;
  on?: ReactNode;
  off?: ReactNode;
} & Omit<ButtonProps, "aria-label" | "children" | "onClick">) {
  const { slots } = useAppShell();
  const resolvedOff = offContent ?? defaultOff;
  const resolvedOn = onContent ?? defaultOn;

  return (
    <Button
      {...rest}
      aria-label={ariaLabel ?? `Toggle ${placement} region`}
      aria-pressed={open}
      className={slots.inline({ className })}
      data-placement={placement}
      data-scope="app-shell"
      data-state={open ? "open" : "closed"}
      onClick={(event) => {
        onClick?.(event);
        toggle();
      }}
      size="icon-md"
      variant="ghost"
    >
      {children ?? <Swap off={resolvedOff} on={resolvedOn} swap={open} />}
    </Button>
  );
}

// #region Display Names
AppShellSideTrigger.displayName = "AppShell.SideTrigger";
// #endregion

import { Children, isValidElement, type ReactNode } from "react";
import type { AppShellPlacement } from "./app-shell.context";

export interface AppShellSlots {
  banner: ReactNode;
  inspectors: Record<AppShellPlacement, ReactNode>;
  main: ReactNode;
  navigation: ReactNode;
  panels: Record<AppShellPlacement, ReactNode>;
  rails: Record<AppShellPlacement, ReactNode>;
}

function getDisplayName(type: unknown): string | undefined {
  if (
    typeof type === "function" ||
    (typeof type === "object" && type !== null)
  ) {
    return (type as { displayName?: string }).displayName;
  }

  return undefined;
}

export function partitionAppShellChildren(children: ReactNode): AppShellSlots {
  const slots: AppShellSlots = {
    banner: null,
    inspectors: { end: null, start: null },
    main: null,
    navigation: null,
    panels: { end: null, start: null },
    rails: { end: null, start: null },
  };

  Children.forEach(children, (child) => {
    if (!isValidElement(child)) {
      return;
    }

    const name = getDisplayName(child.type);
    const props = child.props as { placement?: AppShellPlacement };
    const placement = props.placement ?? "start";

    switch (name) {
      case "AppShell.Banner":
        slots.banner = child;
        break;
      case "AppShell.Inspector":
        slots.inspectors[placement] = child;
        break;
      case "AppShell.Main":
        slots.main = child;
        break;
      case "AppShell.Navigation":
        slots.navigation = child;
        break;
      case "AppShell.Panel":
        slots.panels[placement] = child;
        break;
      case "AppShell.Rail":
        slots.rails[placement] = child;
        break;
      default:
        break;
    }
  });

  return slots;
}

import { AppShellRoot } from "./app-shell";
import { AppShellBanner } from "./banner";
import {
  AppShellInspector,
  AppShellInspectorContent,
  AppShellInspectorFooter,
  AppShellInspectorHeader,
  AppShellInspectorTrigger,
} from "./inspector";
import { AppShellContent, AppShellHeader, AppShellMain } from "./main";
import { AppShellNavigation } from "./navigation";
import {
  AppShellPanel,
  AppShellPanelContent,
  AppShellPanelFooter,
  AppShellPanelHeader,
  AppShellPanelTrigger,
} from "./panel";
import { AppShellRail, AppShellRailItem } from "./rail";

export type { AppShellRootProps } from "./app-shell";
export type {
  AppShellPlacement,
  AppShellRailState,
  AppShellRegionPosition,
  AppShellRegionVar,
  AppShellResizableProps,
  AppShellResizeHandlePosition,
  AppShellSideState,
} from "./app-shell.context";
export { useAppShell } from "./app-shell.context";
export type { AppShellBannerProps } from "./banner";
export type {
  AppShellInspectorContentProps,
  AppShellInspectorFooterProps,
  AppShellInspectorHeaderProps,
  AppShellInspectorProps,
  AppShellInspectorTriggerProps,
} from "./inspector";
export type {
  AppShellContentProps,
  AppShellHeaderProps,
  AppShellMainProps,
} from "./main";
export type { AppShellNavigationProps } from "./navigation";
export type {
  AppShellPanelContentProps,
  AppShellPanelFooterProps,
  AppShellPanelHeaderProps,
  AppShellPanelProps,
  AppShellPanelTriggerProps,
} from "./panel";
export type { AppShellRailItemProps, AppShellRailProps } from "./rail";
export { useAppShellRail } from "./rail.context";

export const AppShell = Object.assign(AppShellRoot, {
  Banner: AppShellBanner,
  Content: AppShellContent,
  Header: AppShellHeader,
  Inspector: AppShellInspector,
  InspectorContent: AppShellInspectorContent,
  InspectorFooter: AppShellInspectorFooter,
  InspectorHeader: AppShellInspectorHeader,
  InspectorTrigger: AppShellInspectorTrigger,
  Main: AppShellMain,
  Navigation: AppShellNavigation,
  Panel: AppShellPanel,
  PanelContent: AppShellPanelContent,
  PanelFooter: AppShellPanelFooter,
  PanelHeader: AppShellPanelHeader,
  PanelTrigger: AppShellPanelTrigger,
  Rail: AppShellRail,
  RailItem: AppShellRailItem,
});

