import {
  type AvatarFallbackProps,
  type AvatarImageProps,
  Avatar as AvatarPrimitive,
  type AvatarRootProps as AvatarPrimitiveRootProps,
} from "@ark-ui/react/avatar";
import type { AvatarProps as BaseAvatarRootProps } from "@pisagor/props";
import { type AvatarRecipeSlot, avatarRecipe } from "@pisagor/recipes";
import type { ComponentProps, FunctionComponent, ReactNode } from "react";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import type { VariantClassNames } from "../../internal/types";

// #region Context
const { withContext, withProvider } = createSlotRecipeContext({
  name: "Avatar",
  recipe: avatarRecipe,
});
// #endregion

// #region Parts
const AvatarRoot = withProvider(AvatarPrimitive.Root, {
  name: "Root",
  slot: "base",
}) as FunctionComponent<AvatarPrimitiveRootProps & BaseAvatarRootProps>;

const AvatarImage = withContext(AvatarPrimitive.Image, {
  name: "Image",
});

const AvatarFallback = withContext(AvatarPrimitive.Fallback, {
  name: "Fallback",
});
// #endregion

// #region Types
type AvatarClassNames = VariantClassNames<AvatarRecipeSlot>;

export interface AvatarProps
  extends Omit<ComponentProps<typeof AvatarRoot>, "children"> {
  /** Alt text for the avatar image */
  alt?: string;
  /** Renders the fallback content shown until the image loads */
  fallback?: ReactNode;
  /** Renders the avatar image with the provided src */
  src?: string;
  /** Slot class names */
  classNames?: AvatarClassNames;
  /** Extra props forwarded to the avatar fallback element */
  fallbackProps?: Omit<AvatarFallbackProps, "children" | "className">;
  /** Extra props forwarded to the avatar image element */
  imageProps?: Omit<AvatarImageProps, "alt" | "className" | "src">;
}
// #endregion

// #region Closed
export function Avatar({
  shape,
  size,
  alt,
  fallback,
  fallbackProps,
  imageProps,
  src,
  classNames,
  ...rest
}: AvatarProps) {
  return (
    <AvatarRoot {...rest} shape={shape} size={size}>
      {src && (
        <AvatarImage
          {...imageProps}
          alt={alt}
          className={classNames?.image}
          src={src}
        />
      )}

      {fallback !== undefined && (
        <AvatarFallback {...fallbackProps} className={classNames?.fallback}>
          {fallback}
        </AvatarFallback>
      )}
    </AvatarRoot>
  );
}
// #endregion

// #region Display Names
Avatar.displayName = "Avatar";
// #endregion

import { ark } from "@ark-ui/react/factory";
import type { AvatarGroupProps as BaseAvatarGroupRootProps } from "@pisagor/props";
import { avatarGroupRecipe } from "@pisagor/recipes";
import type { ComponentProps, FunctionComponent } from "react";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import { Avatar } from "./avatar";

// #region Context
const { withContext, withProvider } = createSlotRecipeContext({
  name: "AvatarGroup",
  recipe: avatarGroupRecipe,
});
// #endregion

// #region Parts
export const AvatarGroupRoot = withProvider(ark.div, {
  name: "Root",
  slot: "base",
}) as FunctionComponent<
  ComponentProps<typeof ark.div> & BaseAvatarGroupRootProps
>;

export const AvatarGroupCount = withContext(ark.div, {
  name: "Count",
});
// #endregion

// #region Types
export type AvatarGroupRootProps = ComponentProps<typeof AvatarGroupRoot>;
export type AvatarGroupCountProps = ComponentProps<typeof AvatarGroupCount>;

export interface AvatarGroupProps
  extends Omit<ComponentProps<typeof AvatarGroupRoot>, "children"> {
  /** Maximum number of avatars to show; excess shown as "+N". */
  max?: number;
  /** User list rendered as avatars. */
  users: Array<{ src?: string; fallback?: string; name?: string }>;
}
// #endregion

// #region Shorthand
export function AvatarGroupShorthand({
  max,
  users,
  ...rest
}: AvatarGroupProps) {
  const visibleUsers = max !== undefined ? users.slice(0, max) : users;
  const remainingCount =
    max !== undefined && users.length > max ? users.length - max : 0;

  return (
    <AvatarGroupRoot {...rest}>
      {visibleUsers.map((user) => (
        <Avatar
          alt={user.name ?? ""}
          fallback={user.fallback}
          key={user.src ?? user.fallback ?? user.name}
          src={user.src}
        />
      ))}
      {remainingCount > 0 ? (
        <AvatarGroupCount>+{remainingCount}</AvatarGroupCount>
      ) : null}
    </AvatarGroupRoot>
  );
}
// #endregion

// #region Display Names
AvatarGroupShorthand.displayName = "AvatarGroup";
// #endregion

import {
  AvatarGroupCount,
  AvatarGroupRoot,
  AvatarGroupShorthand,
} from "./avatar-group";

export type {
  AvatarFallbackProps,
  AvatarImageProps,
} from "@ark-ui/react/avatar";

export { Avatar, type AvatarProps } from "./avatar";
export type {
  AvatarGroupCountProps,
  AvatarGroupProps,
  AvatarGroupRootProps,
} from "./avatar-group";

export const AvatarGroup = Object.assign(AvatarGroupShorthand, {
  Count: AvatarGroupCount,
  Root: AvatarGroupRoot,
});

