import {
  type CheckboxIndicatorProps,
  Checkbox as CheckboxPrimitive,
  type CheckboxGroupProps as CheckboxPrimitiveGroupProps,
  type CheckboxRootProps,
} from "@ark-ui/react/checkbox";
import { CheckIcon, MinusIcon } from "@phosphor-icons/react";
import type {
  CheckboxGroupProps as BaseCheckboxGroupProps,
  CheckboxProps as BaseCheckboxProps,
} from "@pisagor/props";
import {
  checkboxGroupRecipe,
  checkboxRecipe,
  formControlToggleRecipe,
} from "@pisagor/recipes";

import { cn } from "@pisagor/utils";
import { useFormControlSurface } from "./surface/use-form-control-surface";

// #region Types
type FormControlVariant = "primary" | "secondary";

export interface CheckboxGroupProps
  extends Omit<CheckboxPrimitiveGroupProps, "onValueChange">,
    BaseCheckboxGroupProps {
  onValueChange?: (value: string[]) => void;
}

export interface CheckboxProps extends CheckboxRootProps, BaseCheckboxProps {
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
  onValueChange?: (value: boolean) => void;
}

type CheckboxIndicatorPartProps = CheckboxIndicatorProps & {
  recipe?: typeof checkboxRecipe;
};

// #endregion

// #region Parts
export function CheckboxGroup({
  onValueChange,
  recipe = checkboxGroupRecipe,
  className,
  ...rest
}: CheckboxGroupProps) {
  return (
    <CheckboxPrimitive.Group
      {...rest}
      className={recipe({ className })}
      onValueChange={onValueChange}
    />
  );
}

export function CheckboxRoot({
  variant: variantProp,
  tabIndex,
  onCheckedChange,
  onValueChange,
  recipe = checkboxRecipe,
  className,
  ...rest
}: CheckboxProps) {
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: variantProp ?? ("primary" as FormControlVariant),
  };
  const shellArgs = {
    surfaceVariant: resolved.surfaceVariant,
    variant: resolved.variant,
  };
  const controlProps = { "data-variant": resolved.variant };
  const slots = recipe();

  const handleCheckedChange =
    onCheckedChange || onValueChange
      ? (
          details: Parameters<NonNullable<CheckboxProps["onCheckedChange"]>>[0],
        ) => {
          onCheckedChange?.(details);
          onValueChange?.(details.checked === true);
        }
      : undefined;

  return (
    <CheckboxPrimitive.Root
      {...rest}
      {...controlProps}
      className={cn(
        formControlToggleRecipe({ size: "md", ...shellArgs }),
        slots.base({ className }),
      )}
      onCheckedChange={handleCheckedChange}
      role="checkbox"
    >
      <CheckboxPrimitive.Control>
        <CheckboxIndicator recipe={recipe}>
          <CheckIcon />
        </CheckboxIndicator>

        <CheckboxIndicator indeterminate recipe={recipe}>
          <MinusIcon />
        </CheckboxIndicator>
      </CheckboxPrimitive.Control>

      <CheckboxPrimitive.HiddenInput tabIndex={tabIndex} />
    </CheckboxPrimitive.Root>
  );
}

function CheckboxIndicator({
  className,
  recipe = checkboxRecipe,
  ...rest
}: CheckboxIndicatorPartProps) {
  const slots = recipe();

  return (
    <CheckboxPrimitive.Indicator
      {...rest}
      className={slots.indicator({ className })}
    />
  );
}
// #endregion

// #region Display Names
CheckboxGroup.displayName = "Checkbox.Group";
CheckboxRoot.displayName = "Checkbox";
CheckboxIndicator.displayName = "Checkbox.Indicator";

// #endregion

export type {
  CheckboxCheckedState,
  CheckboxRootProps,
} from "@ark-ui/react/checkbox";

export const Checkbox = Object.assign(CheckboxRoot, {
  Group: CheckboxGroup,
});

