import type { CollectionItem } from "@ark-ui/react/collection";
import { Portal } from "@ark-ui/react/portal";
import { MagnifyingGlassIcon } from "@phosphor-icons/react";
import type {
  CommandProps as BaseCommandDialogContentProps,
  CommandProps as BaseCommandProps,
} from "@pisagor/props";
import { commandRecipe } from "@pisagor/recipes";
import type { ComponentProps } from "react";
import { createSlotRecipeContext } from "../internal/create-slot-recipe-context";
import type {
  ComboboxContentProps,
  ComboboxEmptyProps,
  ComboboxFieldInputProps,
  ComboboxItemGroupLabelProps,
  ComboboxItemGroupProps,
  ComboboxItemProps,
  ComboboxListProps,
  ComboboxRootProps,
} from "./combobox";
import { Combobox } from "./combobox";
import {
  Dialog,
  type DialogContentProps,
  type DialogTriggerProps,
} from "./dialog";
import type { InputProps } from "./input";
import { InputGroup } from "./input-group";
import { Separator } from "./separator";

// #region Context
const { Context: CommandStylesContext, useStyles: useCommand } =
  createSlotRecipeContext({
    name: "Command",
    recipe: commandRecipe,
  });
// #endregion

// #region Types
export interface CommandDialogContentProps
  extends DialogContentProps,
    BaseCommandDialogContentProps {
  /**
   * The description of the dialog
   *
   * @defaultValue "Search for a command to run..."
   */
  description?: string;
  /**
   * The title of the dialog
   *
   * @defaultValue "Command Palette"
   */
  title?: string;
}

export interface CommandInputProps
  extends Omit<ComboboxFieldInputProps, "size"> {
  /**
   * The size of the input
   *
   * @defaultValue "md"
   */
  size?: InputProps["size"];
}

export type CommandListProps = ComboboxListProps;

export type CommandContentProps = ComboboxContentProps;

export interface CommandProps<T extends CollectionItem = CollectionItem>
  extends Omit<ComboboxRootProps<T>, "recipe">,
    BaseCommandProps {
  className?: string;
}

export type CommandSeparatorProps = ComponentProps<"div">;

export type CommandShortcutProps = ComponentProps<"span">;

export type CommandFooterProps = ComponentProps<"div">;
// #endregion

// #region Parts
export const CommandDialog = Dialog.Root;

export function CommandDialogTrigger(props: DialogTriggerProps) {
  return <Dialog.Trigger {...props} />;
}

export function CommandDialogContent({
  size = "lg",
  children,
  description = "Search for a command to run...",
  title = "Command Palette",
  recipe = commandRecipe,
  className,
  ...rest
}: CommandDialogContentProps) {
  const slots = recipe();

  return (
    <CommandStylesContext value={{ slots, variants: {} as never }}>
      <Portal>
        <Dialog.Backdrop />

        <Dialog.Positioner>
          <Dialog.Content
            {...rest}
            className={slots.dialogContent({ className })}
            showCloseButton={false}
            size={size}
          >
            <Dialog.Header className={slots.dialogHeader()}>
              <Dialog.Title>{title}</Dialog.Title>
              <Dialog.Description>{description}</Dialog.Description>
            </Dialog.Header>

            {children}
          </Dialog.Content>
        </Dialog.Positioner>
      </Portal>
    </CommandStylesContext>
  );
}

export function CommandRoot<T extends CollectionItem = CollectionItem>({
  recipe = commandRecipe,
  className,
  ...rest
}: CommandProps<T>) {
  const slots = recipe();

  return (
    <CommandStylesContext value={{ slots, variants: {} as never }}>
      <Combobox.Root
        {...rest}
        className={slots.base({ className })}
        closeOnSelect={false}
        disableLayer
        inputBehavior="autohighlight"
        loopFocus={false}
        open
        selectionBehavior="clear"
      />
    </CommandStylesContext>
  );
}

export function CommandContent({ className, ...rest }: CommandContentProps) {
  const { slots } = useCommand();

  return (
    <Combobox.Content
      {...rest}
      className={slots.content({ className })}
      portalled={false}
    />
  );
}

export function CommandInput({ size, className, ...rest }: CommandInputProps) {
  const { slots } = useCommand();

  return (
    <Combobox.Control className={slots.control()}>
      <InputGroup {...rest} className={slots.input({ className })} size={size}>
        <InputGroup.Addon>
          <MagnifyingGlassIcon aria-hidden className={slots.inputIcon()} />
        </InputGroup.Addon>
        <Combobox.FieldInput asChild>
          <InputGroup.Input autoFocus />
        </Combobox.FieldInput>
      </InputGroup>
    </Combobox.Control>
  );
}

export function CommandList({ className, ...rest }: CommandListProps) {
  const { slots } = useCommand();

  return (
    <div className={slots.listWrapper()}>
      <Combobox.List {...rest} className={slots.list({ className })} />
    </div>
  );
}

export function CommandEmpty({
  children,
  className,
  ...rest
}: ComboboxEmptyProps) {
  const { slots } = useCommand();

  return (
    <Combobox.Empty {...rest} className={slots.empty({ className })}>
      {children || "No results found. Try a different search."}
    </Combobox.Empty>
  );
}

export function CommandItemGroup(props: ComboboxItemGroupProps) {
  return <Combobox.ItemGroup {...props} />;
}

export function CommandItemGroupLabel(props: ComboboxItemGroupLabelProps) {
  return <Combobox.ItemGroupLabel {...props} />;
}

export function CommandItem({ className, ...rest }: ComboboxItemProps) {
  return (
    <Combobox.Item {...rest} className={className} showIndicator={false} />
  );
}

export function CommandSeparator({
  className,
  ...rest
}: CommandSeparatorProps) {
  const { slots } = useCommand();

  return (
    <Separator
      {...rest}
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="command"
    />
  );
}

export function CommandShortcut({ className, ...rest }: CommandShortcutProps) {
  const { slots } = useCommand();

  return (
    <span
      {...rest}
      className={slots.shortcut({ className })}
      data-part="shortcut"
      data-scope="command"
    />
  );
}

export function CommandFooter({ className, ...rest }: CommandFooterProps) {
  const { slots } = useCommand();

  return (
    <div
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="command"
    />
  );
}
// #endregion

// #region Display Names
CommandDialog.displayName = "Command.Dialog";
CommandDialogTrigger.displayName = "Command.DialogTrigger";
CommandDialogContent.displayName = "Command.DialogContent";
CommandRoot.displayName = "Command";
CommandContent.displayName = "Command.Content";
CommandInput.displayName = "Command.Input";
CommandList.displayName = "Command.List";
CommandEmpty.displayName = "Command.Empty";
CommandItemGroup.displayName = "Command.ItemGroup";
CommandItemGroupLabel.displayName = "Command.ItemGroupLabel";
CommandItem.displayName = "Command.Item";
CommandSeparator.displayName = "Command.Separator";
CommandShortcut.displayName = "Command.Shortcut";
CommandFooter.displayName = "Command.Footer";
// #endregion

export const Command = Object.assign(CommandRoot, {
  Content: CommandContent,
  Dialog: CommandDialog,
  DialogContent: CommandDialogContent,
  DialogTrigger: CommandDialogTrigger,
  Empty: CommandEmpty,
  Footer: CommandFooter,
  Input: CommandInput,
  Item: CommandItem,
  ItemGroup: CommandItemGroup,
  ItemGroupLabel: CommandItemGroupLabel,
  List: CommandList,
  Separator: CommandSeparator,
  Shortcut: CommandShortcut,
});

import {
  type MenuContextTriggerProps,
  Menu as MenuPrimitive,
} from "@ark-ui/react/menu";
import type { ContextMenuProps as BaseContextMenuContextTriggerProps } from "@pisagor/props";
import { contextMenuRecipe } from "@pisagor/recipes";
import type {
  DropdownMenuContentProps,
  DropdownMenuItemGroupProps,
  DropdownMenuItemProps,
  DropdownMenuRootProps,
  DropdownMenuSeparatorProps,
  DropdownMenuShortcutProps,
  DropdownMenuTriggerItemProps,
} from "./dropdown-menu";
import { DropdownMenu } from "./dropdown-menu";

// #region Types
export type ContextMenuRootProps = DropdownMenuRootProps;

export interface ContextMenuContextTriggerProps
  extends MenuContextTriggerProps,
    BaseContextMenuContextTriggerProps {}
// #endregion

// #region Parts
export function ContextMenuRoot({ ...rest }: ContextMenuRootProps) {
  return <DropdownMenu {...rest} />;
}

export function ContextMenuContextTrigger({
  recipe = contextMenuRecipe,
  className,
  ...rest
}: ContextMenuContextTriggerProps) {
  return (
    <MenuPrimitive.ContextTrigger {...rest} className={recipe({ className })} />
  );
}

export function ContextMenuContent(props: DropdownMenuContentProps) {
  return <DropdownMenu.Content {...props} />;
}

export function ContextMenuItemGroup(props: DropdownMenuItemGroupProps) {
  return <DropdownMenu.ItemGroup {...props} />;
}

export function ContextMenuSeparator(props: DropdownMenuSeparatorProps) {
  return <DropdownMenu.Separator {...props} />;
}

export function ContextMenuItem(props: DropdownMenuItemProps) {
  return <DropdownMenu.Item {...props} />;
}

export function ContextMenuSub(props: DropdownMenuRootProps) {
  return <DropdownMenu.Sub {...props} />;
}

export function ContextMenuSubContent(props: DropdownMenuContentProps) {
  return <DropdownMenu.SubContent {...props} />;
}

export function ContextMenuTriggerItem(props: DropdownMenuTriggerItemProps) {
  return <DropdownMenu.TriggerItem {...props} />;
}

export function ContextMenuShortcut(props: DropdownMenuShortcutProps) {
  return (
    <DropdownMenu.Shortcut
      {...props}
      data-part="shortcut"
      data-scope="context-menu"
    />
  );
}
// #endregion

// #region Display Names
ContextMenuRoot.displayName = "ContextMenu";
ContextMenuContextTrigger.displayName = "ContextMenu.ContextTrigger";
ContextMenuContent.displayName = "ContextMenu.Content";
ContextMenuItemGroup.displayName = "ContextMenu.ItemGroup";
ContextMenuSeparator.displayName = "ContextMenu.Separator";
ContextMenuItem.displayName = "ContextMenu.Item";
ContextMenuSub.displayName = "ContextMenu.Sub";
ContextMenuSubContent.displayName = "ContextMenu.SubContent";
ContextMenuTriggerItem.displayName = "ContextMenu.TriggerItem";
ContextMenuShortcut.displayName = "ContextMenu.Shortcut";
// #endregion

export const ContextMenu = Object.assign(ContextMenuRoot, {
  Content: ContextMenuContent,
  ContextTrigger: ContextMenuContextTrigger,
  Item: ContextMenuItem,
  ItemGroup: ContextMenuItemGroup,
  Separator: ContextMenuSeparator,
  Shortcut: ContextMenuShortcut,
  Sub: ContextMenuSub,
  SubContent: ContextMenuSubContent,
  TriggerItem: ContextMenuTriggerItem,
});

