function SelectionSummary<TData extends RowData>({
  onClear,
}: {
  onClear: () => void;
}) {
  const table = useDataGrid<TData>();
  const selected = table.getFilteredSelectedRowModel().rows.length;
  if (selected === 0) {
    return null;
  }
  return (
    <div className="flex items-center justify-between gap-3 pt-1">
      <p className="text-muted-foreground text-sm">{selected} selected</p>
      <Button onClick={onClear} size="sm" variant="ghost">
        Clear selection
      </Button>
    </div>
  );
}

function GlobalSelectionSummary<TData extends RowData>({
  onClear,
}: {
  onClear: () => void;
}) {
  return <SelectionSummary<TData> onClear={onClear} />;
}

export function GlobalSelection() {
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({
    "2": true,
    "5": true,
  });
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 6,
  });
  const columns = useUserColumns({ selectable: true });

  return (
    <DataGridShell>
      <DataGrid<User>
        columns={columns}
        data={allUsers}
        enableRowSelection
        getRowId={(row: User) => row.id}
        onPaginationChange={setPagination}
        onRowSelectionChange={setRowSelection}
        state={{ pagination, rowSelection }}
      >
        <DataGrid.Toolbar>
          <GlobalSelectionSummary<User> onClear={() => setRowSelection({})} />
        </DataGrid.Toolbar>
        <DataGridView colSpan={7} />
        <DataGridPaginationBar<User> />
      </DataGrid>
    </DataGridShell>
  );
