                      {user.email}
                    </p>
                  </div>
                  <Badge variant="secondary">{user.role}</Badge>
                </Sortable.ItemContent>
              </Sortable.Item>
            ))}
          </Sortable>
          <DataGridView colSpan={5} />
        </div>
      </DataGrid>
    </DataGridShell>
  );
}

