        </p>
        <ul className="space-y-1">
          {searchResults.map((item) => (
            <li className="text-base text-foreground" key={item}>
              {query ? (
                <Highlight ignoreCase query={query} text={item} />
              ) : (
                item
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

