import { ark } from "@ark-ui/react/factory";
import type { ItemProps as BaseItemProps } from "@pisagor/props";
import { type ItemVariantProps, itemRecipe } from "@pisagor/recipes";
import type { ComponentProps } from "react";
import { createSlotRecipeContext } from "../../internal/create-slot-recipe-context";
import { useItemGroup } from "./item-group.context";

// #region Context
const {
  Context: ItemStylesContext,
  useStyles: useItem,
  withContext,
} = createSlotRecipeContext({
  name: "Item",
  recipe: itemRecipe,
});
// #endregion

// #region Parts
export function ItemRoot({
  variant: variantProp,
  children,
  recipe = itemRecipe,
  className,
  ...rest
}: ComponentProps<typeof ark.div> & BaseItemProps) {
  const group = useItemGroup();
  const variant = variantProp ?? group?.variant ?? "default";
  const resolved = {
    ...itemRecipe.defaultVariants,
    ...recipe.defaultVariants,
    variant,
  };
  const slots = recipe(resolved);

  return (
    <ItemStylesContext value={{ slots, variants: resolved as never }}>
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-scope="item"
        data-variant={variant}
      >
        {children}
      </ark.div>
    </ItemStylesContext>
  );
}

export function ItemMedia({
  variant = "default",
  children,
  className,
  ...rest
}: ComponentProps<typeof ark.div> & ItemVariantProps) {
  const { slots } = useItem();

  return (
    <ark.div
      {...rest}
      className={slots.media({ className, variant })}
      data-part="media"
      data-scope="item"
      data-variant={variant}
    >
      {children}
    </ark.div>
  );
}

export const ItemContent = withContext(ark.div, {
  name: "Content",
  slot: "content",
});

export const ItemTitle = withContext(ark.div, {
  name: "Title",
  slot: "title",
});

export const ItemDescription = withContext(ark.p, {
  name: "Description",
  slot: "description",
});

export const ItemActions = withContext(ark.div, {
  name: "Actions",
  slot: "actions",
});

export const ItemHeader = withContext(ark.div, {
  name: "Header",
  slot: "header",
});

export const ItemFooter = withContext(ark.div, {
  name: "Footer",
  slot: "footer",
});
// #endregion

// #region Types
export type ItemProps = ComponentProps<typeof ItemRoot>;
export type ItemMediaProps = ComponentProps<typeof ItemMedia>;
export type ItemHeaderProps = ComponentProps<typeof ItemHeader>;
export type ItemContentProps = ComponentProps<typeof ItemContent>;
export type ItemTitleProps = ComponentProps<typeof ItemTitle>;
export type ItemDescriptionProps = ComponentProps<typeof ItemDescription>;
export type ItemActionsProps = ComponentProps<typeof ItemActions>;
export type ItemFooterProps = ComponentProps<typeof ItemFooter>;
// #endregion

ItemRoot.displayName = "Item";
ItemMedia.displayName = "Item.Media";

import type { ItemVariantProps } from "@pisagor/recipes";

import { createContext } from "../../utils";

export type ItemGroupContextValue = ItemVariantProps;

export const { ItemGroupContext, useItemGroup } = createContext(
  "ItemGroup",
)<ItemGroupContextValue>({ strict: false });

import { ark } from "@ark-ui/react/factory";
import type {
  ItemProps as BaseItemGroupProps,
  ItemProps as BaseItemSeparatorProps,
} from "@pisagor/props";
import { itemRecipe } from "@pisagor/recipes";
import type { ComponentProps } from "react";
import { Separator, type SeparatorProps } from "../separator";
import { ItemGroupContext } from "./item-group.context";

// #region Types
export interface ItemGroupProps
  extends ComponentProps<typeof ark.div>,
    BaseItemGroupProps {}

export interface ItemSeparatorProps
  extends Omit<SeparatorProps, "recipe">,
    BaseItemSeparatorProps {}
// #endregion

// #region Parts
export function ItemGroup({
  variant = "default",
  children,
  recipe = itemRecipe,
  className,
  ...rest
}: ItemGroupProps) {
  const slots = recipe();

  return (
    <ItemGroupContext value={{ variant }}>
      <ark.div
        {...rest}
        className={slots.group({ className })}
        data-part="group"
        data-scope="item"
        data-variant={variant}
        role="list"
      >
        {children}
      </ark.div>
    </ItemGroupContext>
  );
}

export function ItemSeparator({
  recipe = itemRecipe,
  className,
  ...rest
}: ItemSeparatorProps) {
  const slots = recipe();

  return (
    <Separator
      {...rest}
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="item"
      orientation="horizontal"
    />
  );
}
// #endregion

// #region Display Names
ItemGroup.displayName = "Item.Group";
ItemSeparator.displayName = "Item.Separator";
// #endregion

import {
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemFooter,
  ItemHeader,
  ItemMedia,
  ItemRoot,
  ItemTitle,
} from "./item";
import { ItemGroup, ItemSeparator } from "./item-group";

export type {
  ItemActionsProps,
  ItemContentProps,
  ItemDescriptionProps,
  ItemFooterProps,
  ItemHeaderProps,
  ItemMediaProps,
  ItemProps,
  ItemTitleProps,
} from "./item";
export type { ItemGroupProps, ItemSeparatorProps } from "./item-group";

export const Item = Object.assign(ItemRoot, {
  Actions: ItemActions,
  Content: ItemContent,
  Description: ItemDescription,
  Footer: ItemFooter,
  Group: ItemGroup,
  Header: ItemHeader,
  Media: ItemMedia,
  Separator: ItemSeparator,
  Title: ItemTitle,
});

