import { ark } from "@ark-ui/react/factory";
import type { SeparatorProps as BaseSeparatorProps } from "@pisagor/props";
import { separatorRecipe } from "@pisagor/recipes";
import type { ComponentProps } from "react";

// #region Types
export interface SeparatorProps
  extends ComponentProps<typeof ark.div>,
    BaseSeparatorProps {
  /**
   * The orientation of the separator.
   *
   * @defaultValue "horizontal"
   */
  orientation?: "horizontal" | "vertical";
}
// #endregion

// #region Component
export function Separator({
  orientation = "horizontal",
  recipe = separatorRecipe,
  className,
  ...rest
}: SeparatorProps) {
  return (
    <ark.div
      {...rest}
      aria-orientation={orientation}
      className={recipe({ className })}
      data-orientation={orientation}
      data-part="root"
      data-scope="separator"
      role="separator"
    />
  );
}
// #endregion

import type {
  DialogCloseTriggerProps,
  DialogContentProps,
  DialogPositionerProps,
  DialogTriggerProps,
} from "@ark-ui/react/dialog";
import { Dialog as DialogPrimitive } from "@ark-ui/react/dialog";
import { Portal } from "@ark-ui/react/portal";
import { XIcon } from "@phosphor-icons/react";
import type { SheetProps as BaseSheetProps } from "@pisagor/props";
import { type SheetVariantProps, sheetRecipe } from "@pisagor/recipes";
import { createSlotRecipeContext } from "../internal/create-slot-recipe-context";
import { Button } from "./button";
import type {
  DialogBackdropProps,
  DialogBodyProps,
  DialogDescriptionProps,
  DialogFooterProps,
  DialogHeaderProps,
  DialogRootProps,
  DialogTitleProps,
} from "./dialog";
import { Dialog } from "./dialog";

// #region Context
const { Context: SheetStylesContext, useStyles: useSheet } =
  createSlotRecipeContext({
    name: "Sheet",
    recipe: sheetRecipe,
  });
// #endregion

// #region Types
export type SheetPositionerProps = DialogPositionerProps & SheetVariantProps;

export interface SheetContentProps
  extends DialogContentProps,
    SheetVariantProps {
  /**
   * Whether to show a close button at the top right corner.
   *
   * @defaultValue true
   */
  showCloseButton?: boolean;
}

export interface SheetProps extends DialogRootProps, BaseSheetProps {}

export type SheetTriggerProps = DialogTriggerProps;

export type SheetCloseTriggerProps = DialogCloseTriggerProps;
// #endregion

// #region Parts
export function SheetRoot({ recipe = sheetRecipe, ...rest }: SheetProps) {
  const slots = recipe();

  return (
    <SheetStylesContext value={{ slots, variants: {} as never }}>
      <Dialog.Root {...rest} />
    </SheetStylesContext>
  );
}

export function SheetTrigger(props: SheetTriggerProps) {
  return <DialogPrimitive.Trigger {...props} />;
}

export function SheetBackdrop(props: DialogBackdropProps) {
  return <Dialog.Backdrop {...props} />;
}

export function SheetPositioner({
  placement,
  variant = "default",
  className,
  ...rest
}: SheetPositionerProps) {
  const { slots } = useSheet();

  return (
    <DialogPrimitive.Positioner
      {...rest}
      className={slots.positioner({ className, placement, variant })}
    />
  );
}

export function SheetContent({
  placement = "right",
  variant = "default",
  showCloseButton = true,
  children,
  className,
  ...rest
}: SheetContentProps) {
  const { slots } = useSheet();

  return (
    <Portal>
      <SheetBackdrop />

      <SheetPositioner placement={placement} variant={variant}>
        <DialogPrimitive.Content
          {...rest}
          className={slots.content({ className, placement, variant })}
        >
          {children}

          {!!showCloseButton && (
            <SheetCloseTrigger asChild>
              <Button
                aria-label="Close"
                className={slots.inline()}
                size="icon-sm"
                variant="ghost"
              >
                <XIcon />
              </Button>
            </SheetCloseTrigger>
          )}
        </DialogPrimitive.Content>
      </SheetPositioner>
    </Portal>
  );
}

export function SheetHeader(props: DialogHeaderProps) {
  return <Dialog.Header {...props} data-part="header" data-scope="sheet" />;
}

export function SheetTitle(props: DialogTitleProps) {
  return <Dialog.Title {...props} />;
}

export function SheetDescription(props: DialogDescriptionProps) {
  return <Dialog.Description {...props} />;
}

export function SheetBody({ className, ...rest }: DialogBodyProps) {
  const { slots } = useSheet();

  return (
    <Dialog.Body
      {...rest}
      className={slots.body({ className })}
      data-part="body"
      data-scope="sheet"
    />
  );
}

export function SheetCloseTrigger(props: SheetCloseTriggerProps) {
  return <DialogPrimitive.CloseTrigger {...props} />;
}

export function SheetFooter({ className, ...rest }: DialogFooterProps) {
  const { slots } = useSheet();

  return (
    <Dialog.Footer
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="sheet"
    />
  );
}
// #endregion

// #region Display Names
SheetRoot.displayName = "Sheet";
SheetTrigger.displayName = "Sheet.Trigger";
SheetBackdrop.displayName = "Sheet.Backdrop";
SheetPositioner.displayName = "Sheet.Positioner";
SheetContent.displayName = "Sheet.Content";
SheetHeader.displayName = "Sheet.Header";
SheetTitle.displayName = "Sheet.Title";
SheetDescription.displayName = "Sheet.Description";
SheetBody.displayName = "Sheet.Body";
SheetCloseTrigger.displayName = "Sheet.CloseTrigger";
SheetFooter.displayName = "Sheet.Footer";
// #endregion

export const Sheet = Object.assign(SheetRoot, {
  Backdrop: SheetBackdrop,
  Body: SheetBody,
  CloseTrigger: SheetCloseTrigger,
  Content: SheetContent,
  Description: SheetDescription,
  Footer: SheetFooter,
  Header: SheetHeader,
  Positioner: SheetPositioner,
  Title: SheetTitle,
  Trigger: SheetTrigger,
});

import { useHotkey } from "@ark-ui/react";
import { ark } from "@ark-ui/react/factory";
import { SidebarSimpleIcon } from "@phosphor-icons/react";
import type { SidebarProps as BaseSidebarProviderProps } from "@pisagor/props";
import {
  type ButtonVariantProps,
  buttonRecipe,
  sidebarRecipe,
} from "@pisagor/recipes";

import { cn } from "@pisagor/utils";
import {
  type ComponentProps,
  type CSSProperties,
  createContext,
  use,
  useCallback,
  useMemo,
  useState,
} from "react";
import { useIsMobile } from "../hooks";
import { createSlotRecipeContext } from "../internal/create-slot-recipe-context";
import { Button, type ButtonProps } from "./button";
import { Input, type InputProps } from "./input";
import { ScrollArea } from "./scroll-area";
import { Separator, type SeparatorProps } from "./separator";
import { Sheet, type SheetProps } from "./sheet";
import { Skeleton } from "./skeleton";
import { Tooltip, type TooltipProps } from "./tooltip";

// #region Context
const { Context: SidebarStylesContext, useStyles: useSidebarStyles } =
  createSlotRecipeContext({
    name: "Sidebar",
    recipe: sidebarRecipe,
  });

interface SidebarState {
  isMobile: boolean;
  open: boolean;
  openMobile: boolean;
  setOpen: (open: boolean) => void;
  setOpenMobile: (open: boolean) => void;
  state: "expanded" | "collapsed";
  toggleSidebar: () => void;
}

const SidebarStateContext = createContext<SidebarState | undefined>(undefined);
SidebarStateContext.displayName = "SidebarStateContext";

export type SidebarContextProps = SidebarState & {
  /** Slot class recipes from `sidebarRecipe`. */
  slots: ReturnType<typeof sidebarRecipe>;
};

/**
 * Returns the nearest sidebar styles + state.
 */
export function useSidebar(): SidebarContextProps {
  const styles = useSidebarStyles();
  const state = use(SidebarStateContext);
  if (state === undefined) {
    throw new Error("useSidebar must be used within SidebarStateContext.");
  }
  return { ...styles, ...state };
}
// #endregion

// #region Types
export interface SidebarProviderProps
  extends ComponentProps<"div">,
    BaseSidebarProviderProps {
  /**
   * The default open state of the sidebar.
   *
   * @defaultValue true
   *
   * @remarks
   * Ignored when `open` is set.
   */
  defaultOpen?: boolean;
  /**
   * The open state of the sidebar.
   *
   * @remarks
   * When set, `defaultOpen` is ignored. Pair with `onOpenChange` to handle updates.
   */
  open?: boolean;
  /**
   * Called when the open state of the sidebar changes.
   *
   * @remarks
   * Each update also persists the expanded/collapsed state in `localStorage` under the `sidebar_state` key.
   */
  onOpenChange?: (open: boolean) => void;
}

export interface SidebarProps
  extends Omit<SheetProps, "placement" | "recipe" | "variant"> {
  placement?: "left" | "right";
  variant?: "sidebar" | "floating" | "inset";
  collapsible?: "offcanvas" | "icon" | "none";
  className?: string;
}

export interface SidebarContentProps extends ComponentProps<"div"> {
  /**
   * Whether to add a scroll fade effect to the sidebar content.
   *
   * @defaultValue false
   */
  scrollFade?: boolean;
}

export interface SidebarMenuButtonProps extends ButtonProps {
  /**
   * Whether the button is active.
   *
   * @defaultValue false
   */
  isActive?: boolean;
  /**
   * The tooltip to display when hovering over the button.
   *
   */
  tooltip?: string | Omit<TooltipProps, "children">;
}

export interface SidebarMenuActionProps
  extends ComponentProps<typeof ark.button> {
  showOnHover?: boolean;
  /**
   * Button style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  buttonRecipe?: typeof buttonRecipe;
}

export interface SidebarMenuSkeletonProps
  extends ComponentProps<typeof ark.div> {
  showIcon?: boolean;
}

export interface SidebarMenuSubButtonProps
  extends ComponentProps<typeof ark.a>,
    ButtonVariantProps {
  isActive?: boolean;
  /**
   * Button style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  buttonRecipe?: typeof buttonRecipe;
}

export type SidebarRailProps = ComponentProps<typeof ark.button>;

export type SidebarInsetProps = ComponentProps<typeof ark.main>;

export type SidebarHeaderProps = ComponentProps<typeof ark.div>;

export type SidebarFooterProps = ComponentProps<typeof ark.div>;

export type SidebarGroupProps = ComponentProps<typeof ark.div>;

export type SidebarGroupLabelProps = ComponentProps<typeof ark.div>;

export interface SidebarGroupActionProps
  extends ComponentProps<typeof ark.button> {
  /**
   * Button style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  buttonRecipe?: typeof buttonRecipe;
}

export type SidebarGroupContentProps = ComponentProps<typeof ark.div>;

export type SidebarMenuProps = ComponentProps<typeof ark.ul>;

export type SidebarMenuItemProps = ComponentProps<typeof ark.li>;

export type SidebarMenuBadgeProps = ComponentProps<typeof ark.div>;

export type SidebarMenuSubProps = ComponentProps<typeof ark.ul>;

export type SidebarMenuSubItemProps = ComponentProps<typeof ark.li>;
// #endregion

// #region Constants
const SIDEBAR_STORAGE_KEY = "sidebar_state";

const SIDEBAR_WIDTH = "16rem";

const SIDEBAR_WIDTH_MOBILE = "18rem";

const SIDEBAR_WIDTH_ICON = "3rem";
// #endregion

// #region Parts
export function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  recipe = sidebarRecipe,
  className,
  style,
  ...rest
}: SidebarProviderProps) {
  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = useState(false);

  const [_open, _setOpen] = useState(defaultOpen);
  const open = openProp ?? _open;
  const setOpen = useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value;
      if (setOpenProp) {
        setOpenProp(openState);
      } else {
        _setOpen(openState);
      }

      localStorage.setItem(SIDEBAR_STORAGE_KEY, String(openState));
    },
    [setOpenProp, open],
  );

  const toggleSidebar = useCallback(() => {
    if (isMobile) {
      setOpenMobile((open) => !open);
    } else {
      setOpen((open) => !open);
    }
  }, [isMobile, setOpen]);

  useHotkey({
    action: () => {
      toggleSidebar();
    },
    hotkey: "mod+B",
  });

  const state = open ? "expanded" : "collapsed";
  const slots = recipe();

  const stateValue = useMemo<SidebarState>(
    () => ({
      isMobile,
      open,
      openMobile,
      setOpen,
      setOpenMobile,
      state,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, toggleSidebar],
  );

  return (
    <SidebarStylesContext value={{ slots, variants: {} as never }}>
      <SidebarStateContext value={stateValue}>
        <ark.div
          {...rest}
          className={slots.wrapper({ className })}
          data-part="wrapper"
          data-scope="sidebar"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH,
              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
              ...style,
            } as CSSProperties
          }
        />
      </SidebarStateContext>
    </SidebarStylesContext>
  );
}

export function SidebarRoot(props: SidebarProps) {
  const {
    collapsible = "offcanvas",
    placement = "left",
    variant = "sidebar",
    className,
    children,
    ...rest
  } = props;
  const { isMobile, openMobile, setOpenMobile, slots, state } = useSidebar();
  const padded = variant === "floating" || variant === "inset";

  if (collapsible === "none") {
    return (
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-scope="sidebar"
      >
        {children}
      </ark.div>
    );
  }

  if (isMobile) {
    return (
      <Sheet onOpenChange={({ open }) => setOpenMobile(open)} open={openMobile}>
        <Sheet.Content
          {...rest}
          className={slots.mobile()}
          data-mobile="true"
          data-sidebar="sidebar"
          placement={placement === "left" ? "left" : "right"}
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as CSSProperties
          }
        >
          <Sheet.Header className={slots.mobileHeader()}>
            <Sheet.Title>Sidebar</Sheet.Title>
            <Sheet.Description>Displays the mobile sidebar.</Sheet.Description>
          </Sheet.Header>
          <ark.div className={slots.mobileBody()}>{children}</ark.div>
        </Sheet.Content>
      </Sheet>
    );
  }

  return (
    <ark.div
      {...rest}
      className={slots.peer({ className })}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-part="root"
      data-placement={placement}
      data-scope="sidebar"
      data-state={state}
      data-variant={variant}
    >
      <ark.div
        className={slots.gap({ padded, placement })}
        data-part="gap"
        data-scope="sidebar"
      />
      <ark.div
        className={slots.container({ className, padded, placement })}
        data-part="container"
        data-scope="sidebar"
      >
        <ark.div
          className={slots.inner()}
          data-part="inner"
          data-scope="sidebar"
          data-sidebar="sidebar"
        >
          {children}
        </ark.div>
      </ark.div>
    </ark.div>
  );
}

export function SidebarTrigger({ onClick, className, ...rest }: ButtonProps) {
  const { slots, toggleSidebar } = useSidebar();

  return (
    <Button
      {...rest}
      className={slots.trigger({ className })}
      data-part="trigger"
      data-scope="sidebar"
      data-sidebar="trigger"
      onClick={(event) => {
        onClick?.(event);
        toggleSidebar();
      }}
      size="icon-md"
      variant="ghost"
    >
      <SidebarSimpleIcon className={slots.triggerIcon()} />
      <ark.span className={slots.triggerLabel()}>Toggle sidebar</ark.span>
    </Button>
  );
}

export function SidebarRail({ className, ...rest }: SidebarRailProps) {
  const { slots, toggleSidebar } = useSidebar();

  return (
    <ark.button
      {...rest}
      aria-label="Toggle sidebar"
      className={slots.rail({ className })}
      data-part="rail"
      data-scope="sidebar"
      data-sidebar="rail"
      onClick={toggleSidebar}
      tabIndex={-1}
      title="Toggle sidebar"
      type="button"
    />
  );
}

export function SidebarInset({ className, ...rest }: SidebarInsetProps) {
  const { slots } = useSidebar();

  return (
    <ark.main
      {...rest}
      className={slots.inset({ className })}
      data-part="inset"
      data-scope="sidebar"
    />
  );
}

export function SidebarInput({ className, classNames, ...rest }: InputProps) {
  const { slots } = useSidebar();

  return (
    <Input
      {...rest}
      className={slots.input({ className })}
      classNames={classNames}
      data-sidebar="input"
    />
  );
}

export function SidebarHeader({ className, ...rest }: SidebarHeaderProps) {
  const { slots } = useSidebar();

  return (
    <ark.div
      {...rest}
      className={slots.header({ className })}
      data-part="header"
      data-scope="sidebar"
      data-sidebar="header"
    />
  );
}

export function SidebarFooter({ className, ...rest }: SidebarFooterProps) {
  const { slots } = useSidebar();

  return (
    <ark.div
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="sidebar"
      data-sidebar="footer"
    />
  );
}

export function SidebarSeparator({ className, ...rest }: SeparatorProps) {
  const { slots } = useSidebar();

  return (
    <Separator
      {...rest}
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="sidebar"
      data-sidebar="separator"
    />
  );
}

export function SidebarContent({
  scrollFade = false,
  className,
  ...rest
}: SidebarContentProps) {
  const { slots } = useSidebar();

  return (
    <ScrollArea className={slots.scrollArea()} scrollFade={scrollFade}>
      <ark.div
        {...rest}
        className={slots.content({ className })}
        data-part="content"
        data-scope="sidebar"
        data-sidebar="content"
      />
    </ScrollArea>
  );
}

export function SidebarGroup({ className, ...rest }: SidebarGroupProps) {
  const { slots } = useSidebar();

  return (
    <ark.div
      {...rest}
      className={slots.group({ className })}
      data-part="group"
      data-scope="sidebar"
      data-sidebar="group"
    />
  );
}

export function SidebarGroupLabel({
  className,
  ...rest
}: SidebarGroupLabelProps) {
  const { slots } = useSidebar();

  return (
    <ark.div
      {...rest}
      className={slots.groupLabel({ className })}
      data-part="group-label"
      data-scope="sidebar"
      data-sidebar="group-label"
    />
  );
}

export function SidebarGroupAction({
  buttonRecipe: buttonRecipeProp = buttonRecipe,
  className,
  ...rest
}: SidebarGroupActionProps) {
  const { slots } = useSidebar();

  return (
    <ark.button
      {...rest}
      className={cn(
        buttonRecipeProp({
          clickEffect: false,
          size: "icon-xs",
          variant: "ghost",
        }).base(),
        slots.groupAction(),
        className,
      )}
      data-part="group-action"
      data-scope="sidebar"
      data-sidebar="group-action"
      type="button"
    />
  );
}

export function SidebarGroupContent({
  className,
  ...rest
}: SidebarGroupContentProps) {
  const { slots } = useSidebar();

  return (
    <ark.div
      {...rest}
      className={slots.groupContent({ className })}
      data-part="group-content"
      data-scope="sidebar"
      data-sidebar="group-content"
    />
  );
}

export function SidebarMenu({ className, ...rest }: SidebarMenuProps) {
  const { slots } = useSidebar();

  return (
    <ark.ul
      {...rest}
      className={slots.menu({ className })}
      data-part="menu"
      data-scope="sidebar"
      data-sidebar="menu"
    />
  );
}

export function SidebarMenuItem({ className, ...rest }: SidebarMenuItemProps) {
  const { slots } = useSidebar();

  return (
    <ark.li
      {...rest}
      className={slots.menuItem({ className })}
      data-part="menu-item"
      data-scope="sidebar"
      data-sidebar="menu-item"
    />
  );
}

export function SidebarMenuButton({
  size = "md",
  variant = "ghost",
  isActive = false,
  tooltip,
  className,
  ...rest
}: SidebarMenuButtonProps) {
  const { isMobile, slots, state } = useSidebar();

  const button = (
    <Button
      {...rest}
      className={slots.menuButton({ className })}
      clickEffect={false}
      data-active={isActive}
      data-part="menu-button"
      data-scope="sidebar"
      data-sidebar="menu-button"
      data-size={size}
      size={size}
      variant={variant}
    />
  );

  if (!tooltip) {
    return button;
  }

  if (typeof tooltip === "string") {
    tooltip = { content: tooltip };
  }

  return (
    <Tooltip
      {...tooltip}
      contentProps={{
        ...tooltip.contentProps,
        hidden: state !== "collapsed" || isMobile,
      }}
      positioning={{ placement: "right", ...tooltip.positioning }}
    >
      {button}
    </Tooltip>
  );
}

export function SidebarMenuAction({
  showOnHover = false,
  buttonRecipe: buttonRecipeProp = buttonRecipe,
  className,
  ...rest
}: SidebarMenuActionProps) {
  const { slots } = useSidebar();

  return (
    <ark.button
      {...rest}
      className={cn(
        buttonRecipeProp({
          clickEffect: false,
          size: "icon-xs",
          variant: "ghost",
        }).base(),
        slots.menuAction(),
        !showOnHover &&
          "group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 data-[state=open]:opacity-100 peer-data-[active=true]/menu-button:text-accent-foreground md:opacity-0",
        className,
      )}
      data-part="menu-action"
      data-scope="sidebar"
      data-sidebar="menu-action"
