          <Sortable.Item key={id} value={id}>
            <Sortable.ItemContent>
              <Sortable.Handle />
              <span className="font-medium text-sm">{labels[id]}</span>
            </Sortable.ItemContent>
          </Sortable.Item>
        ))}
      </Sortable>
    </div>
  );
}

