import { ArrowUpIcon } from "@phosphor-icons/react";
import { Stat } from "@pisagor/react";

export function Compound() {
  return (
    <Stat.Root>
      <Stat.Label>Monthly recurring revenue</Stat.Label>
      <Stat.Value>$124,320</Stat.Value>
      <Stat.Trend trend="up">
        <ArrowUpIcon />
