import { ark } from "@ark-ui/react/factory";
import type { SurfaceProps as BaseSurfaceProps } from "@pisagor/props";
import { surfaceRecipe } from "@pisagor/recipes";
import type { ComponentProps } from "react";
import { useMemo } from "react";
import {
  SurfaceContext,
  type SurfaceVariant,
  useSurface,
} from "./surface.context";

// #region Types
const AUTO_VARIANTS = [
  "default",
  "secondary",
  "tertiary",
  "tertiary",
] as const satisfies readonly SurfaceVariant[];

export interface SurfaceProps
  extends ComponentProps<typeof ark.div>,
    BaseSurfaceProps {}
// #endregion

// #region Component
export function Surface({
  bordered = false,
  rounded = true,
  variant: variantProp,
  children,
  padding,
  recipe = surfaceRecipe,
  className,
  ...rest
}: SurfaceProps) {
  const parent = useSurface();

  const surface = useMemo(() => {
    const depth = parent ? parent.depth + 1 : 0;
    const variant =
      variantProp ??
      AUTO_VARIANTS[Math.min(depth, AUTO_VARIANTS.length - 1)] ??
      "default";

    return { depth, variant };
  }, [parent, variantProp]);

  return (
    <SurfaceContext value={surface}>
      <ark.div
        {...rest}
        className={recipe({
          bordered,
          className,
          padding,
          rounded,
          variant: surface.variant,
        })}
        data-depth={surface.depth}
        data-part="root"
        data-scope="surface"
        data-variant={surface.variant}
      >
        {children}
      </ark.div>
    </SurfaceContext>
  );
}
// #endregion

import type { SurfaceVariantProps } from "@pisagor/recipes";

import { createContext } from "../../utils";

export type SurfaceVariant = NonNullable<SurfaceVariantProps["variant"]>;

export interface SurfaceContextValue {
  depth: number;
  variant: SurfaceVariant;
}

export const { SurfaceContext, useSurface } = createContext(
  "Surface",
)<SurfaceContextValue>({ strict: false });

import type { FormControlShellVariantProps } from "@pisagor/recipes";

import { useSurface } from "./surface.context";

export type FormControlSurfaceVariant =
  FormControlShellVariantProps["surfaceVariant"];

/**
 * Resolves the nearest Surface variant for form-control shell fills.
 * Does not change primary/secondary shell variant — only surface contrast.
 */
export function useFormControlSurface(): FormControlSurfaceVariant {
  return useSurface()?.variant;
}

export { Surface, type SurfaceProps } from "./surface";
export type { SurfaceContextValue, SurfaceVariant } from "./surface.context";

export { useSurface } from "./surface.context";
export { useFormControlSurface } from "./use-form-control-surface";

