import { waitForElement, waitForEvent } from "@ark-ui/react/tour";
import { PlusIcon } from "@phosphor-icons/react";
import type { TourStepType } from "@pisagor/react";
import { Button, Tour } from "@pisagor/react";
import { useState } from "react";
export function WaitForElement() {
  const steps: TourStepType[] = [
    {
      actions: [{ action: "next", label: "Start" }],
      description:
        "This tour demonstrates waiting for elements that appear dynamically.",
      id: "intro",
      title: "Dynamic elements",
      type: "dialog",
    },
    {
      description: "Click the button to add a new item to the list.",
      effect({ next, target, show }) {
        show();
        const [promise, cancel] = waitForEvent(target, "click");
        promise.then(() => next());
        return cancel;
      },
      id: "add-item",
      target: () => document.querySelector<HTMLElement>("#btn-add-item"),
      title: "Add an item",
      type: "tooltip",
    },
    {
      actions: [{ action: "next", label: "Next" }],
      description:
        "The tour waited for this element to appear before showing this step.",
      effect({ show }) {
        const [promise, cancel] = waitForElement(
          () => document.querySelector<HTMLElement>('[data-item="new"]'),
          { timeout: 5000 },
        );
        promise.then(() => show());
        return () => cancel();
      },
      id: "new-item",
      target: () => document.querySelector<HTMLElement>('[data-item="new"]'),
      title: "Item added",
      type: "tooltip",
    },
    {
      actions: [{ action: "dismiss", label: "Done" }],
      description: "You learned how to use waitForElement for dynamic content.",
      id: "complete",
      title: "Tour complete",
      type: "dialog",
    },
  ];
  const [items, setItems] = useState(["Item 1", "Item 2"]);

  const addItem = () => {
    setItems((prev) => [...prev, `Item ${prev.length + 1}`]);
  };

  return (
    <div className="flex flex-col gap-2">
      <Tour steps={steps}>
        <Tour.Trigger asChild>
          <Button variant="outline">Start tour</Button>
        </Tour.Trigger>
        <div className="flex flex-col gap-2">
          <Button
            id="btn-add-item"
            onClick={addItem}
            size="sm"
            variant="outline"
          >
            <PlusIcon className="size-4" />
            Add Item
          </Button>
          <div className="flex flex-col gap-2">
            {items.map((item, index) => (
              <div
                className="rounded-lg border border-border bg-muted/50 px-4 py-3 text-sm"
                data-item={
                  index === items.length - 1 && items.length > 2
                    ? "new"
                    : undefined
                }
                key={item}
              >
                {item}
              </div>
            ))}
          </div>
        </div>
        <Tour.Content>
          <Tour.Header>
            <Tour.ProgressText />
            <Tour.Title />
            <Tour.Description />
          </Tour.Header>
          <Tour.Actions />
        </Tour.Content>
      </Tour>
    </div>
  );
}

import { waitForEvent } from "@ark-ui/react/tour";
import type { TourStepType } from "@pisagor/react";
import { Button, Checkbox, Field, Input, Tour } from "@pisagor/react";
export function WaitForInput() {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const steps: TourStepType[] = [
    {
      actions: [{ action: "next", label: "Start" }],
      description:
        "Learn how to fill out the form by following the guided steps.",
      id: "intro",
      title: "Form tutorial",
      type: "dialog",
    },
    {
      description: "Type your name in the input field to continue.",
      effect({ next, target, show }) {
        show();
        const [promise, cancel] = waitForEvent<HTMLInputElement>(
          target,
          "input",
          {
            predicate: (el) => el.value.trim().length >= 2,
          },
        );
        promise.then(() => next());
        return cancel;
      },
      id: "enter-name",
      target: () => document.querySelector<HTMLInputElement>("#input-name"),
      title: "Enter your name",
      type: "tooltip",
    },
    {
      description: "Now enter a valid email address.",
      effect({ next, target, show }) {
        show();
        const [promise, cancel] = waitForEvent<HTMLInputElement>(
          target,
          "input",
          {
            predicate: (el) => emailRegex.test(el.value),
          },
        );
        promise.then(() => next());
        return cancel;
      },
      id: "enter-email",
      target: () => document.querySelector<HTMLInputElement>("#input-email"),
      title: "Enter your email",
      type: "tooltip",
    },
    {
      description: "Check the checkbox to accept the terms.",
      effect({ next, target, show }) {
        show();
        const [promise, cancel] = waitForEvent<HTMLInputElement>(
          target,
          "change",
          {
            predicate: (el) => el.checked,
          },
        );
        promise.then(() => next());
        return cancel;
      },
      id: "check-terms",
      target: () => document.querySelector<HTMLInputElement>("#checkbox-terms"),
      title: "Accept terms",
      type: "tooltip",
    },
    {
      actions: [{ action: "dismiss", label: "Done" }],
      description: "You have successfully filled out the form.",
      id: "complete",
      title: "Form complete",
      type: "dialog",
    },
  ];
  return (
    <div className="flex flex-col gap-2">
      <Tour steps={steps}>
        <Tour.Trigger asChild>
          <Button variant="outline">Start form tutorial</Button>
        </Tour.Trigger>
        <div className="flex flex-col gap-2 rounded-lg border border-border bg-muted/50 p-4">
          <Field>
            <Field.Label htmlFor="input-name">Name</Field.Label>
            <Input id="input-name" placeholder="Enter your name" type="text" />
          </Field>
          <Field>
            <Field.Label htmlFor="input-email">Email</Field.Label>
            <Input
              id="input-email"
              placeholder="Enter your email"
              type="email"
            />
          </Field>
          <Field orientation="horizontal">
            <Checkbox id="checkbox-terms" />
            <Field.Label htmlFor="checkbox-terms">
              I accept the terms and conditions
            </Field.Label>
          </Field>
        </div>
        <Tour.Content>
          <Tour.Header>
            <Tour.ProgressText />
            <Tour.Title />
            <Tour.Description />
          </Tour.Header>
          <Tour.Actions />
        </Tour.Content>
      </Tour>
    </div>
  );
}

